import{_ as s,l as r,o as e,c as l,v as t,p as n,x as o,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"JIT 中的逃逸分析","description":"","frontmatter":{"title":"JIT 中的逃逸分析","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/jit-escape-analysis.md","filePath":"cs/jit-escape-analysis.md","lastUpdated":1789023840000}'),h={name:"cs/jit-escape-analysis.md"};function E(A,a,_,T,m,u){const i=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="jit-中的逃逸分析" tabindex="-1">JIT 中的逃逸分析 <a class="header-anchor" href="#jit-中的逃逸分析" aria-label="Permalink to &quot;JIT 中的逃逸分析&quot;">​</a></h1><div class="epigraph"><p>在热方法的编译单元里做逃逸分析：未逃逸则可标量化、拆锁、栈分配。比 AOT 更敢，因为去优化能在假设失败时物化对象。</p><footer>—— 据 Choi 等；HotSpot 逃逸分析；对照中端[逃逸分析](/cs/escape-analysis) 整理</footer></div><p>上一课<a href="/cs/tiered-compilation">分层编译</a> 的顶层才跑贵分析。中端 EA 课已给 NoEscape。缺口是 <strong>JIT 增量</strong>：编译单元是内联后的一片，不是全程序；失败靠<a href="/cs/deoptimization">去优化</a> 物化。本课钉差异，内存管理单元下一课从 GC 算法接。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>AOT 无 deopt，EA 必须对所有调用保守。JIT：未知调用若在本方法内联消失，对象未逃逸。锁消除：线程局部对象的 synchronized 可删。缺口是<strong>与去优化合同</strong>，不是 Choi 算法重推。</p><p>循环分配：若对象每圈 new 且不逃逸，可标量化成寄存器——垃圾更少。</p><h3 id="jit-ea-不是-gc" tabindex="-1">JIT EA 不是 GC <a class="header-anchor" href="#jit-ea-不是-gc" aria-label="Permalink to &quot;JIT EA 不是 GC&quot;">​</a></h3><p>它减少分配，GC 仍处理逃逸对象。不要声称 EA 替代回收。</p><p><span class="marginnote">HotSpot EA。与 Choi/Blanchet 同一问题，不同失败通道。本课强调物化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>内联后跑连接图或数据流。标记标量替换候选。生成码不分配，deopt 描述符记录如何 new 回来。</p>',11)),(e(),n(c,null,{default:o(()=>[d(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20INL%5B%22%E5%86%85%E8%81%94%E5%90%8E%20IR%22%5D%20--%3E%20EA%5B%22%E9%80%83%E9%80%B8%E5%88%86%E6%9E%90%22%5D%0A%20%20EA%20--%3E%20SROA%5B%22%E6%A0%87%E9%87%8F%E5%8C%96%20%2F%20%E5%8E%BB%E9%94%81%22%5D%0A%20%20SROA%20--%3E%20DEOPT%5B%22%E5%A4%B1%E8%B4%A5%E5%88%99%E7%89%A9%E5%8C%96%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与<a href="/cs/sroa">SROA</a>：同一变换，JIT 因开世界+deopt 收益更大。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>并发：分析时类层次可再加载 → 失效码。安全点与锁膨胀交互复杂。不要消除可能被其它线程看见的锁。</p><p>分配消除改变 TLAB 压力，后课 bump 分配再谈。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 GC 算法。后课默认：顶层 JIT 可激进 EA。下一课复制式 GC：堆侧如何收仍逃逸的对象。</p><p>也不把 EA 当所有权类型；那是静态纪律。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>JIT EA 吃内联后的闭包，失败靠物化。</li><li>锁消除与标量化是主要收益。</li><li>不替代 GC。</li><li>出处：Choi et al.；HotSpot EA；对照 Hölzle 去优化。</li></ul>',9))])}const I=s(h,[["render",E]]);export{C as __pageData,I as default};
